"""Core type definitions for backend-agnostic LLM communication."""

from typing import Any, Literal

from pydantic import BaseModel, Field

RoleType = Literal["system", "user", "assistant", "tool"]


class ToolCall(BaseModel):
    """Represents a tool call invocation generated by an LLM."""

    id: str = Field(default="", description="Unique identifier for the tool call invocation.")
    name: str = Field(description="Name of the function/tool to execute.")
    arguments: dict[str, Any] = Field(
        default_factory=dict,
        description="Parsed arguments to pass to the tool.",
    )


class Message(BaseModel):
    """Chat message exchanged between the user, agent, and tools."""

    role: RoleType = Field(description="The role of the message sender.")
    content: str = Field(default="", description="Textual body of the message.")
    tool_calls: list[ToolCall] | None = Field(
        default=None,
        description="Tool calls requested by the assistant.",
    )
    tool_call_id: str | None = Field(
        default=None,
        description="The ID of the tool call this message responds to.",
    )


class ToolSpec(BaseModel):
    """Specification of an executable tool provided to the LLM."""

    name: str = Field(description="Unique name of the tool.")
    description: str = Field(description="Human-readable description of what the tool does.")
    parameters: dict[str, Any] = Field(
        default_factory=dict,
        description="JSON Schema describing the parameters accepted by the tool.",
    )

    def to_ollama_format(self) -> dict[str, Any]:
        """Convert specification to Ollama native tools parameter format."""
        return {
            "type": "function",
            "function": {
                "name": self.name,
                "description": self.description,
                "parameters": self.parameters,
            },
        }


class Usage(BaseModel):
    """Token usage and execution metrics for a completion."""

    prompt_tokens: int = Field(default=0, description="Tokens consumed by the prompt.")
    completion_tokens: int = Field(default=0, description="Tokens generated in the completion.")
    total_tokens: int = Field(default=0, description="Total tokens processed.")
    duration_ms: float = Field(
        default=0.0,
        description="Total duration in milliseconds.",
    )


class StreamChunk(BaseModel):
    """Individual streamed delta or terminal event from an LLM."""

    delta: str = Field(default="", description="Incremental text fragment.")
    tool_call_delta: ToolCall | None = Field(
        default=None,
        description="Incremental or completed tool call emitted during streaming.",
    )
    done: bool = Field(default=False, description="Whether this is the final chunk in the stream.")
    finish_reason: str | None = Field(
        default=None,
        description="Reason generation terminated (e.g. stop, tool_calls).",
    )
    usage: Usage | None = Field(
        default=None,
        description="Usage statistics provided on terminal chunk.",
    )
